from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]

def read(path):
    return (ROOT / path).read_text()

def write(path, content):
    target = ROOT / path
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(content)

def replace_once(path, old, new, label=None):
    content = read(path)
    count = content.count(old)
    if count != 1:
        raise RuntimeError(f"{label or path}: expected one match, found {count}")
    write(path, content.replace(old, new, 1))

write('index.html', '<!doctype html>\n<html lang="en">\n<head>\n  <meta charset="utf-8">\n  <meta name="viewport" content="width=device-width, initial-scale=1">\n  <meta name="referrer" content="strict-origin-when-cross-origin">\n  <meta name="theme-color" content="#0e1116">\n  <meta name="description" content="Read YouTube videos as ordered spatial ranges using refinement, Pins, and Sections.">\n  <title>Binary YouTube Reader</title>\n  <link rel="icon" href="favicon.svg" type="image/svg+xml">\n  <link rel="stylesheet" href="styles.css">\n  <link rel="stylesheet" href="step-field.css">\n  <link rel="stylesheet" href="field-grammar.css">\n</head>\n<body>\n  <main class="app-shell">\n    <header id="load-bar" class="load-bar">\n      <div class="brand-block">\n        <div>\n          <h1>Binary YouTube Reader</h1>\n          <p>Resolve a video spatially, retain Addresses as Pins, and focus bounded Sections as the active Range.</p>\n        </div>\n      </div>\n      <div class="load-actions">\n        <div class="url-row">\n          <label class="sr-only" for="youtube-url">YouTube URL</label>\n          <input id="youtube-url" type="url" inputmode="url" autocomplete="off" placeholder="Paste a YouTube link">\n          <button id="load-video" class="primary" type="button">Load</button>\n        </div>\n        <button id="guide-toggle" class="guide-toggle" type="button" aria-controls="guide-panel" aria-expanded="true">\n          <span>Guide</span>\n          <span class="guide-toggle-count"><span id="header-section-count">0</span>/<span id="header-pin-count">0</span></span>\n          <kbd>G</kbd>\n        </button>\n      </div>\n    </header>\n\n    <div class="workspace">\n      <section id="reader-column" class="reader-column" aria-label="Video reader">\n        <section class="player-panel" aria-label="Panoramic video field">\n          <div id="step-field" class="step-field field-off" data-phase="off" aria-label="Step Field">\n            <section id="tail-pane" class="step-pane step-pane-side tail-pane" aria-label="Tail Step projection">\n              <div class="step-pane-bar">\n                <div class="pane-identity">\n                  <span class="step-pane-role">Tail</span>\n                  <span id="tail-meta" class="step-pane-meta">—</span>\n                </div>\n                <div class="pane-controls">\n                  <label class="pane-rate-setting" for="tail-rate-select">\n                    <span>Rate</span>\n                    <select id="tail-rate-select" aria-label="Tail playback rate" disabled><option value="0.5">0.5×</option></select>\n                  </label>\n                  <button id="tail-collapse" class="pane-collapse" type="button" aria-label="Hide Tail" title="Hide Tail">×</button>\n                </div>\n              </div>\n              <div class="player-wrap">\n                <div id="player-tail"></div>\n                <button id="tail-step" class="step-pane-action" type="button" aria-label="Select Tail projection" disabled>\n                  <span class="sr-only">Select Tail projection</span>\n                </button>\n              </div>\n              <button id="tail-restore" class="step-pane-restore" type="button" aria-label="Show Tail" hidden>\n                <span aria-hidden="true">←</span><span>Tail</span>\n              </button>\n            </section>\n\n            <section class="step-pane step-pane-center" aria-label="Center video">\n              <div class="step-pane-bar center-bar">\n                <div class="pane-identity">\n                  <span class="step-pane-role">Center</span>\n                  <span id="center-meta" class="step-pane-meta">—</span>\n                </div>\n                <button id="step-field-toggle" class="field-toggle" type="button" aria-pressed="true" aria-label="Hide Step Field">\n                  <span>Field</span><span id="step-field-meta">Ready</span>\n                </button>\n              </div>\n              <div class="player-wrap"><div id="player"></div></div>\n            </section>\n\n            <section id="lead-pane" class="step-pane step-pane-side lead-pane" aria-label="Lead Step projection">\n              <div class="step-pane-bar">\n                <div class="pane-identity">\n                  <span class="step-pane-role">Lead</span>\n                  <span id="lead-meta" class="step-pane-meta">—</span>\n                </div>\n                <div class="pane-controls">\n                  <label class="pane-rate-setting" for="lead-rate-select">\n                    <span>Rate</span>\n                    <select id="lead-rate-select" aria-label="Lead playback rate" disabled><option value="2">2×</option></select>\n                  </label>\n                  <button id="lead-collapse" class="pane-collapse" type="button" aria-label="Hide Lead" title="Hide Lead">×</button>\n                </div>\n              </div>\n              <div class="player-wrap">\n                <div id="player-lead"></div>\n                <button id="lead-step" class="step-pane-action" type="button" aria-label="Select Lead projection" disabled>\n                  <span class="sr-only">Select Lead projection</span>\n                </button>\n              </div>\n              <button id="lead-restore" class="step-pane-restore" type="button" aria-label="Show Lead" hidden>\n                <span>Lead</span><span aria-hidden="true">→</span>\n              </button>\n            </section>\n          </div>\n\n          <div class="field-transport-bar" aria-label="Playback and observation">\n            <span id="field-transport-help" class="sr-only">Continue controls Center and any available Tail and Lead panes. Context, Skim, and Loop use the current semantic operands.</span>\n            <div class="transport-actions">\n              <button id="continue" class="field-transport transport-primary" type="button" aria-keyshortcuts="Space" aria-describedby="field-transport-help" title="Continue or pause Center and available Field panes" disabled>\n                <span id="continue-label">Continue</span>\n                <span id="continue-meta" class="control-meta">—</span>\n              </button>\n              <button id="context-action" class="transport-action" type="button" data-preview-action="context" aria-keyshortcuts="C" disabled>\n                <span id="context-label">Context</span><span id="context-state" class="control-meta">5 s</span>\n              </button>\n              <button id="skim" class="transport-action" type="button" data-preview-action="skim" aria-keyshortcuts="F" disabled>\n                <span id="skim-label">Skim</span><span id="skim-meta" class="control-meta">—</span>\n              </button>\n              <button id="loop" class="transport-action" type="button" data-preview-action="loop" aria-keyshortcuts="L" disabled>\n                <span id="loop-label">Loop</span><span id="loop-meta" class="control-meta">—</span>\n              </button>\n            </div>\n\n            <div class="transport-readouts">\n              <div class="transport-readout">\n                <span>Current</span><strong id="current-label">—</strong>\n              </div>\n              <button id="interval-state" class="transport-readout operand-readout" type="button" aria-controls="section-capture" aria-expanded="false" aria-keyshortcuts="Shift+P" disabled>\n                <span>Interval</span><strong id="interval-label">—</strong><em>Retain</em>\n              </button>\n              <div id="field-span-state" class="transport-readout field-span-state" hidden>\n                <div>\n                  <span>Field Span</span><strong id="field-span-label">—</strong>\n                </div>\n                <div class="extent-actions">\n                  <button id="field-span-loop" class="extent-action" type="button" disabled><span id="field-span-loop-label">Loop</span></button>\n                  <button id="field-span-retain" class="extent-action" type="button" disabled>Retain</button>\n                </div>\n              </div>\n            </div>\n\n            <div class="transport-status">\n              <span id="field-transport-state" class="field-transport-state">Off</span>\n              <span id="field-rate-state" class="field-rate-state">Tail — · Center 1× · Lead —</span>\n            </div>\n          </div>\n\n          <div id="status" class="status" role="status" aria-live="polite">Load a YouTube video to begin.</div>\n        </section>\n\n        <section class="panel timeline-panel" aria-label="Range and temporal map">\n          <div class="panel-heading timeline-heading">\n            <div>\n              <span class="eyebrow">Range</span>\n              <h2>Temporal map</h2>\n            </div>\n            <div class="timeline-header">\n              <span><small>Cursor</small><strong id="cursor-time" aria-label="Observed position">0:00.000</strong></span>\n              <span><small>Duration</small><strong id="duration-time">0:00.000</strong></span>\n            </div>\n          </div>\n\n          <div id="timeline" class="timeline" aria-label="Temporal map. Click inside Range to go directly to an Address.">\n            <div class="track">\n              <div id="range-fill" class="range-fill"></div>\n              <div id="resolution-fill" class="resolution-fill"></div>\n              <div id="interval-fill" class="interval-fill" hidden></div>\n              <div id="section-preview-fill" class="section-preview-fill" hidden></div>\n              <div id="action-preview-fill" class="action-preview-fill" hidden></div>\n              <div id="field-span-fill" class="field-span-fill" hidden></div>\n            </div>\n            <div id="pin-lane" class="pin-lane" aria-label="Pins"></div>\n            <div id="pin-cluster-menu" class="pin-cluster-menu" role="menu" aria-label="Nearby Pins" hidden></div>\n\n            <button id="range-start-handle" class="marker range-handle" type="button" role="slider" aria-label="Range Start" aria-orientation="horizontal" aria-valuemin="0" aria-valuenow="0"></button>\n            <button id="range-end-handle" class="marker range-handle" type="button" role="slider" aria-label="Range End" aria-orientation="horizontal" aria-valuemin="0" aria-valuenow="0"></button>\n            <span id="resolution-start-marker" class="marker resolution-marker" aria-hidden="true"></span>\n            <span id="resolution-end-marker" class="marker resolution-marker" aria-hidden="true"></span>\n            <span id="backward-target-marker" class="marker target-marker" aria-hidden="true"></span>\n            <span id="forward-target-marker" class="marker target-marker" aria-hidden="true"></span>\n            <span id="current-marker" class="marker current-marker" aria-hidden="true"></span>\n            <span id="cursor-marker" class="marker cursor-marker" aria-hidden="true" hidden></span>\n          </div>\n        </section>\n\n        <div class="command-workspace">\n          <aside class="panel parameter-panel" aria-labelledby="parameters-heading">\n            <div class="panel-heading compact-heading">\n              <div>\n                <span class="eyebrow">Inputs and state</span>\n                <h2 id="parameters-heading">Parameters</h2>\n              </div>\n              <p>Values entered here alter the operands used by the centered operators.</p>\n            </div>\n\n            <button id="range-state" class="parameter-state state-button" type="button" aria-controls="range-tools" aria-expanded="false">\n              <span>Active Range</span><strong id="range-label">—</strong>\n            </button>\n\n            <div id="resolution-state" class="parameter-state">\n              <span>Resolution</span><strong id="resolution-label">—</strong>\n            </div>\n\n            <details id="range-tools" class="tool-disclosure">\n              <summary><span>Range tools</span><span id="range-tools-value">—</span></summary>\n              <div class="compact-actions">\n                <button id="range-start-here" type="button" disabled>Start at Current</button>\n                <button id="range-midpoint" type="button" disabled>Go to Midpoint</button>\n                <button id="range-end-here" type="button" disabled>End at Current</button>\n                <button id="full-video-range" type="button" disabled>Full Video</button>\n              </div>\n            </details>\n\n            <details id="step-settings" class="tool-disclosure step-settings">\n              <summary>\n                <span>Step Reach</span>\n                <strong id="step-setting-value">← 10s | 10s →</strong>\n              </summary>\n              <div class="settings-body step-field-settings">\n                <fieldset>\n                  <legend>Geometry</legend>\n                  <label class="link-setting" for="step-link">\n                    <input id="step-link" type="checkbox" checked disabled>\n                    <span>Link directional Reach</span>\n                  </label>\n                  <label class="number-setting" for="step-backward-seconds">\n                    <span>Backward Reach</span>\n                    <span><input id="step-backward-seconds" type="number" min="0.25" max="300" step="0.25" value="10" disabled> seconds</span>\n                  </label>\n                  <label class="number-setting" for="step-forward-seconds">\n                    <span>Forward Reach</span>\n                    <span><input id="step-forward-seconds" type="number" min="0.25" max="300" step="0.25" value="10" disabled> seconds</span>\n                  </label>\n                </fieldset>\n              </div>\n            </details>\n\n            <details id="observation-settings" class="tool-disclosure observation-settings">\n              <summary><span>Observation</span><span>Context · Skim</span></summary>\n              <div class="compact-settings">\n                <label class="compact-setting" for="context-select">\n                  <span>Context duration</span>\n                  <select id="context-select" disabled>\n                    <option value="0">Off</option>\n                    <option value="3">3 s</option>\n                    <option value="5" selected>5 s</option>\n                    <option value="10">10 s</option>\n                  </select>\n                </label>\n                <label class="compact-setting" for="speed-select">\n                  <span>Skim rate</span>\n                  <select id="speed-select" disabled><option value="1">1×</option></select>\n                </label>\n              </div>\n            </details>\n\n            <form id="section-capture" class="capture-bar" hidden>\n              <div>\n                <span id="section-source-label" class="eyebrow capture-source">Retain Interval</span>\n                <strong id="section-window">—</strong>\n              </div>\n              <label class="sr-only" for="section-label">Section title</label>\n              <input id="section-label" type="text" maxlength="100" placeholder="Section title" disabled>\n              <div class="capture-actions">\n                <button id="save-section" class="primary" type="submit" disabled>Save Section</button>\n                <button id="cancel-section" type="button">Cancel</button>\n              </div>\n            </form>\n\n            <details id="shortcut-help" class="tool-disclosure shortcut-help">\n              <summary id="shortcut-help-summary"><span>Keyboard</span><kbd>?</kbd></summary>\n              <div class="shortcut-grid">\n                <span><kbd>W</kbd> Reopen</span>\n                <span><kbd>A</kbd>/<kbd>D</kbd> Refine</span>\n                <span><kbd>←</kbd>/<kbd>→</kbd> Step</span>\n                <span><kbd>S</kbd> Return</span>\n                <span><kbd>⇧←</kbd>/<kbd>⇧→</kbd> Pins</span>\n                <span><kbd>P</kbd> Pin Current</span>\n                <span><kbd>Space</kbd> Continue/Pause</span>\n                <span><kbd>C</kbd> Context</span>\n                <span><kbd>F</kbd> Skim</span>\n                <span><kbd>L</kbd> Loop</span>\n                <span><kbd>⇧P</kbd> Save Section</span>\n                <span><kbd>G</kbd> Guide</span>\n                <span><kbd>[</kbd>/<kbd>]</kbd> Reach preset</span>\n                <span><kbd>Esc</kbd> Stop or close</span>\n              </div>\n            </details>\n          </aside>\n\n          <section class="panel navigation-panel" aria-labelledby="navigation-heading">\n            <div class="panel-heading navigation-heading">\n              <div>\n                <span class="eyebrow">Operator matrix</span>\n                <h2 id="navigation-heading">Navigate</h2>\n              </div>\n              <p>One spatial grammar: reopen, refine, step, return, and cross retained Pins.</p>\n            </div>\n\n            <div class="navigation-deck">\n              <button id="reopen" class="nav-action reopen-action" type="button" data-preview-action="reopen" aria-keyshortcuts="W" disabled>\n                <span class="action-name"><kbd>W</kbd> Reopen</span>\n                <span id="reopen-meta" class="action-meta">—</span>\n              </button>\n\n              <button id="refine-backward" class="nav-action primary direction backward" type="button" data-preview-action="backward" aria-keyshortcuts="A" disabled>\n                <span class="action-name"><kbd>A</kbd> Refine Backward</span>\n                <span id="backward-meta" class="action-meta">—</span>\n              </button>\n\n              <button id="refine-forward" class="nav-action primary direction forward" type="button" data-preview-action="forward" aria-keyshortcuts="D" disabled>\n                <span class="action-name"><kbd>D</kbd> Refine Forward</span>\n                <span id="forward-meta" class="action-meta">—</span>\n              </button>\n\n              <button id="step-backward" class="nav-action direction backward" type="button" data-preview-action="stepBackward" aria-keyshortcuts="ArrowLeft" disabled>\n                <span class="action-name"><kbd>←</kbd> Step Backward</span>\n                <span id="step-backward-meta" class="action-meta">—</span>\n              </button>\n\n              <button id="return-action" class="nav-action history-action" type="button" aria-keyshortcuts="S Control+Z Meta+Z Backspace" disabled>\n                <span class="action-name"><kbd>S</kbd> Return</span>\n                <span id="return-meta" class="action-meta">Nothing to return to</span>\n              </button>\n\n              <button id="step-forward" class="nav-action direction forward" type="button" data-preview-action="stepForward" aria-keyshortcuts="ArrowRight" disabled>\n                <span class="action-name"><kbd>→</kbd> Step Forward</span>\n                <span id="step-forward-meta" class="action-meta">—</span>\n              </button>\n\n              <button id="pin-backward" class="nav-action direction backward" type="button" data-preview-action="previousPin" aria-keyshortcuts="Shift+ArrowLeft" disabled>\n                <span class="action-name"><kbd>⇧←</kbd> Pin Backward</span>\n                <span id="pin-backward-meta" class="action-meta">—</span>\n              </button>\n\n              <button id="pin-current" class="nav-action pin-current-action" type="button" aria-keyshortcuts="P" disabled>\n                <span class="action-name"><kbd>P</kbd> Pin Current</span>\n                <span id="pin-current-meta" class="action-meta">—</span>\n              </button>\n\n              <button id="pin-forward" class="nav-action direction forward" type="button" data-preview-action="nextPin" aria-keyshortcuts="Shift+ArrowRight" disabled>\n                <span class="action-name"><kbd>⇧→</kbd> Pin Forward</span>\n                <span id="pin-forward-meta" class="action-meta">—</span>\n              </button>\n            </div>\n          </section>\n\n          <aside id="guide-panel" class="guide-panel panel" aria-label="Guide" aria-hidden="false">\n            <div class="guide-header">\n              <div>\n                <span class="eyebrow">Retained structure</span>\n                <h2>Guide</h2>\n              </div>\n              <div class="guide-header-actions">\n                <span class="guide-counts"><span id="section-count">0</span> Sections · <span id="pin-count">0</span> Pins</span>\n                <button id="guide-close" class="guide-close" type="button" aria-label="Close Guide">×</button>\n              </div>\n            </div>\n\n            <div class="guide-tabs" role="tablist" aria-label="Guide views">\n              <button id="guide-tab-sections" class="guide-tab active" type="button" role="tab" aria-selected="true" aria-controls="guide-sections-panel" tabindex="0">Sections <span id="sections-list-count">0</span></button>\n              <button id="guide-tab-pins" class="guide-tab" type="button" role="tab" aria-selected="false" aria-controls="guide-pins-panel" tabindex="-1">Pins <span id="pins-list-count">0</span></button>\n              <button id="guide-tab-sources" class="guide-tab" type="button" role="tab" aria-selected="false" aria-controls="guide-sources-panel" tabindex="-1">Sources</button>\n            </div>\n\n            <section id="focused-section" class="focused-section" hidden>\n              <div>\n                <span class="eyebrow">Active Range</span>\n                <strong id="focused-section-title">—</strong>\n                <span id="focused-section-range">—</span>\n              </div>\n              <button id="leave-section" type="button" disabled>Leave</button>\n            </section>\n\n            <section id="guide-sections-panel" class="guide-tab-panel" role="tabpanel" aria-labelledby="guide-tab-sections">\n              <div id="sections-list" class="guide-list"><p class="empty-state">No Sections for this video.</p></div>\n            </section>\n\n            <section id="guide-pins-panel" class="guide-tab-panel" role="tabpanel" aria-labelledby="guide-tab-pins" hidden>\n              <div id="pins-list" class="guide-list"><p class="empty-state">No Pins for this video.</p></div>\n            </section>\n\n            <section id="guide-sources-panel" class="guide-tab-panel source-placeholder" role="tabpanel" aria-labelledby="guide-tab-sources" hidden>\n              <span class="eyebrow">Potential structure</span>\n              <h3>Chapters and transcripts</h3>\n              <p>This boundary is reserved for source-provided potential Pins and Sections. Source records remain external until explicitly retained in the Guide.</p>\n            </section>\n          </aside>\n        </div>\n      </section>\n\n      <button id="guide-scrim" class="guide-scrim" type="button" aria-label="Close Guide" hidden></button>\n    </div>\n\n    <dialog id="guide-dialog" class="guide-dialog" aria-labelledby="guide-dialog-title" aria-describedby="guide-dialog-message" hidden>\n      <form id="guide-dialog-form" method="dialog">\n        <div class="dialog-heading">\n          <span class="eyebrow">Guide</span>\n          <h2 id="guide-dialog-title">Edit retained structure</h2>\n        </div>\n        <p id="guide-dialog-message"></p>\n        <label id="guide-dialog-label" for="guide-dialog-input">Title</label>\n        <input id="guide-dialog-input" type="text" maxlength="100" autocomplete="off">\n        <div class="dialog-actions">\n          <button id="guide-dialog-cancel" type="button">Cancel</button>\n          <button id="guide-dialog-confirm" class="primary" type="submit">Save</button>\n        </div>\n      </form>\n    </dialog>\n  </main>\n\n  <script type="module" src="app.js"></script>\n</body>\n</html>\n')
write('styles.css', ':root {\n  color-scheme: dark;\n  --bg: #0b0e13;\n  --surface: #11161e;\n  --surface-2: #171e28;\n  --surface-3: #202936;\n  --line: #2b3645;\n  --line-strong: #415067;\n  --text: #f2f5f8;\n  --muted: #9ba8b7;\n  --faint: #6f7d8e;\n  --accent: #79a8ff;\n  --accent-strong: #a6c5ff;\n  --accent-soft: rgba(121, 168, 255, 0.14);\n  --pin: #f6c86e;\n  --danger: #ff9b9b;\n  --success: #9fd9b8;\n  --shadow: 0 18px 45px rgba(0, 0, 0, 0.3);\n  --radius: 14px;\n  --radius-small: 9px;\n  --control-height: 40px;\n  --compact-control-height: 32px;\n  --touch: 48px;\n  --content-gap: clamp(8px, 0.9vw, 14px);\n  font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;\n}\n\n* { box-sizing: border-box; }\n[hidden] { display: none !important; }\n\nhtml {\n  background: var(--bg);\n  -webkit-text-size-adjust: 100%;\n}\n\nbody {\n  margin: 0;\n  min-width: 320px;\n  min-height: 100vh;\n  color: var(--text);\n  background:\n    radial-gradient(circle at 18% -10%, rgba(77, 112, 176, 0.16), transparent 34rem),\n    var(--bg);\n}\n\nbutton,\ninput,\nselect,\nsummary {\n  font: inherit;\n}\n\nbutton,\nsummary,\nselect,\n[role="button"] {\n  touch-action: manipulation;\n  -webkit-user-select: none;\n  user-select: none;\n}\n\nbutton {\n  min-height: var(--control-height);\n  border: 1px solid var(--line);\n  border-radius: var(--radius-small);\n  color: var(--text);\n  background: var(--surface-2);\n  cursor: pointer;\n  transition: border-color 120ms ease, background 120ms ease, transform 80ms ease, opacity 120ms ease;\n}\n\nbutton:hover:not(:disabled),\nsummary:hover {\n  border-color: var(--line-strong);\n  background: var(--surface-3);\n}\n\nbutton:active:not(:disabled) { transform: translateY(1px); }\nbutton:disabled { cursor: default; opacity: 0.42; }\n\nbutton:focus-visible,\nsummary:focus-visible,\ninput:focus-visible,\nselect:focus-visible {\n  outline: 2px solid var(--accent);\n  outline-offset: 2px;\n}\n\nbutton.primary {\n  border-color: rgba(121, 168, 255, 0.55);\n  background: linear-gradient(180deg, rgba(89, 137, 226, 0.32), rgba(54, 94, 168, 0.26));\n}\n\ninput,\nselect {\n  min-height: var(--control-height);\n  border: 1px solid var(--line);\n  border-radius: 8px;\n  color: var(--text);\n  background: #0d1219;\n}\n\ninput { padding: 0 0.72rem; }\nselect { padding: 0 1.8rem 0 0.62rem; }\n\nh1, h2, h3, p { margin: 0; }\nh1 { font-size: clamp(1.05rem, 1.5vw, 1.35rem); letter-spacing: -0.025em; }\nh2 { font-size: 1rem; }\nh3 { font-size: 0.92rem; }\np { color: var(--muted); line-height: 1.45; }\n\nkbd {\n  display: inline-grid;\n  min-width: 1.55em;\n  min-height: 1.45em;\n  place-items: center;\n  padding: 0 0.34em;\n  border: 1px solid #526178;\n  border-bottom-color: #334055;\n  border-radius: 5px;\n  color: #dbe7f8;\n  background: #202938;\n  font: 600 0.68rem/1.2 ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;\n  box-shadow: inset 0 -1px 0 rgba(0, 0, 0, 0.35);\n}\n\n.sr-only {\n  position: absolute;\n  width: 1px;\n  height: 1px;\n  padding: 0;\n  margin: -1px;\n  overflow: hidden;\n  clip: rect(0, 0, 0, 0);\n  white-space: nowrap;\n  border: 0;\n}\n\n.app-shell {\n  width: 100%;\n  max-width: none;\n  margin: 0 auto;\n  padding: clamp(8px, 1vw, 16px);\n}\n\n.load-bar {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: 18px;\n  margin-bottom: var(--content-gap);\n  padding: 10px 12px;\n  border: 1px solid var(--line);\n  border-radius: var(--radius);\n  background: rgba(17, 22, 30, 0.92);\n  backdrop-filter: blur(12px);\n  box-shadow: 0 8px 28px rgba(0, 0, 0, 0.18);\n}\n\n.brand-block p {\n  margin-top: 0.18rem;\n  font-size: 0.78rem;\n}\n\n.load-actions {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n}\n\n.url-row {\n  display: grid;\n  grid-template-columns: minmax(260px, 36vw) auto;\n  gap: 7px;\n}\n\n.guide-toggle {\n  display: inline-flex;\n  align-items: center;\n  gap: 7px;\n  padding: 0 10px;\n}\n\n.guide-toggle-count {\n  color: var(--muted);\n  font-size: 0.78rem;\n}\n\n.workspace { display: block; }\n.reader-column {\n  min-width: 0;\n  display: grid;\n  gap: var(--content-gap);\n}\n\n.player-panel,\n.panel,\n.guide-panel,\n.tool-disclosure {\n  border: 1px solid var(--line);\n  border-radius: var(--radius);\n  background: rgba(17, 22, 30, 0.96);\n  box-shadow: 0 10px 34px rgba(0, 0, 0, 0.18);\n}\n\n.player-panel { overflow: hidden; }\n\n.player-wrap {\n  position: relative;\n  width: 100%;\n  aspect-ratio: 16 / 9;\n  background: #000;\n}\n\n.player-wrap > div,\n.player-wrap iframe {\n  width: 100% !important;\n  height: 100% !important;\n}\n\n.status {\n  min-height: 30px;\n  padding: 6px 10px;\n  border-top: 1px solid var(--line);\n  color: var(--muted);\n  background: #0b1017;\n  font-size: 0.75rem;\n}\n\n.status.error { color: var(--danger); }\n\n.panel {\n  min-width: 0;\n  padding: 12px;\n}\n\n.panel-heading {\n  display: flex;\n  align-items: flex-start;\n  justify-content: space-between;\n  gap: 12px;\n  margin-bottom: 10px;\n}\n\n.compact-heading p,\n.navigation-heading p {\n  max-width: 32rem;\n  font-size: 0.75rem;\n}\n\n.eyebrow {\n  display: block;\n  margin-bottom: 2px;\n  color: var(--faint);\n  font-size: 0.63rem;\n  font-weight: 720;\n  letter-spacing: 0.11em;\n  text-transform: uppercase;\n}\n\n/* Timeline is a full-width spatial instrument, not a peer card stretched by another panel. */\n.timeline-panel {\n  padding: 10px 12px 8px;\n}\n\n.timeline-heading {\n  align-items: center;\n  margin-bottom: 2px;\n}\n\n.timeline-header {\n  display: flex;\n  align-items: center;\n  gap: 16px;\n}\n\n.timeline-header span {\n  display: grid;\n  gap: 1px;\n  text-align: right;\n}\n\n.timeline-header small {\n  color: var(--faint);\n  font-size: 0.58rem;\n  font-weight: 700;\n  letter-spacing: 0.08em;\n  text-transform: uppercase;\n}\n\n.timeline-header strong {\n  color: var(--muted);\n  font: 600 0.72rem ui-monospace, SFMono-Regular, Menlo, monospace;\n}\n\n.timeline-header span:first-child strong { color: var(--text); }\n\n.timeline {\n  position: relative;\n  height: 70px;\n  margin: 0 6px;\n  touch-action: pan-y pinch-zoom;\n  cursor: crosshair;\n}\n\n.track {\n  position: absolute;\n  inset: 25px 0 auto;\n  height: 12px;\n  overflow: hidden;\n  border: 1px solid #394558;\n  border-radius: 999px;\n  background: #080b10;\n}\n\n.range-fill,\n.resolution-fill,\n.interval-fill,\n.section-preview-fill,\n.action-preview-fill {\n  position: absolute;\n  top: 0;\n  bottom: 0;\n  pointer-events: none;\n}\n\n.range-fill { background: rgba(101, 126, 164, 0.34); }\n.resolution-fill { background: rgba(121, 168, 255, 0.42); }\n.interval-fill {\n  top: 2px;\n  bottom: 2px;\n  background: rgba(246, 200, 110, 0.58);\n}\n.section-preview-fill { background: rgba(159, 217, 184, 0.35); }\n.action-preview-fill { background: rgba(188, 154, 255, 0.34); }\n.action-preview-fill[data-kind="reopen"] { background: rgba(121, 168, 255, 0.22); }\n\n.marker {\n  position: absolute;\n  top: 17px;\n  z-index: 5;\n  transform: translateX(-50%);\n}\n\n.range-handle {\n  width: 15px;\n  height: 28px;\n  min-height: 28px;\n  padding: 0;\n  border: 0;\n  border-radius: 4px;\n  background: transparent;\n  touch-action: none;\n  cursor: ew-resize;\n}\n\n.range-handle::before {\n  content: "";\n  position: absolute;\n  inset: 6px 5px;\n  border-radius: 2px;\n  background: var(--accent-strong);\n}\n\n.resolution-marker,\n.target-marker,\n.current-marker,\n.cursor-marker {\n  width: 2px;\n  height: 28px;\n  background: #64758b;\n  pointer-events: none;\n}\n\n.target-marker {\n  height: 19px;\n  top: 21px;\n  background: #a58dd0;\n}\n\n.current-marker {\n  z-index: 8;\n  width: 3px;\n  height: 34px;\n  top: 14px;\n  background: #fff;\n  box-shadow: 0 0 0 2px rgba(255, 255, 255, 0.11);\n}\n\n.cursor-marker {\n  z-index: 9;\n  width: 2px;\n  height: 24px;\n  top: 19px;\n  background: var(--accent);\n  box-shadow: 0 0 0 2px rgba(121, 168, 255, 0.13);\n}\n\n.pin-lane {\n  position: absolute;\n  inset: 0;\n  pointer-events: none;\n}\n\n.timeline-pin {\n  position: absolute;\n  top: 45px;\n  width: 18px;\n  height: 18px;\n  min-height: 18px;\n  padding: 0;\n  transform: translateX(-50%);\n  border: 0;\n  border-radius: 50% 50% 50% 0;\n  background: var(--pin);\n  rotate: -45deg;\n  pointer-events: auto;\n}\n\n.timeline-pin::after {\n  content: "";\n  position: absolute;\n  inset: -10px;\n}\n\n.timeline-pin.cluster {\n  width: 24px;\n  height: 24px;\n  top: 42px;\n}\n\n.timeline-pin-count {\n  display: grid;\n  place-items: center;\n  height: 100%;\n  color: #21180a;\n  font-size: 0.65rem;\n  font-weight: 800;\n  rotate: 45deg;\n}\n\n.pin-cluster-menu {\n  position: absolute;\n  top: 66px;\n  z-index: 30;\n  width: 270px;\n  max-height: 240px;\n  overflow: auto;\n  padding: 5px;\n  border: 1px solid var(--line-strong);\n  border-radius: 10px;\n  background: #111824;\n  box-shadow: var(--shadow);\n}\n\n.pin-cluster-menu button {\n  display: flex;\n  width: 100%;\n  justify-content: space-between;\n  gap: 12px;\n  padding: 7px 8px;\n  border: 0;\n  background: transparent;\n  text-align: left;\n}\n\n.pin-cluster-menu time {\n  color: var(--muted);\n  font-size: 0.72rem;\n}\n\n/* Parameters | operators | retained structure */\n.command-workspace {\n  display: grid;\n  gap: var(--content-gap);\n  align-items: start;\n}\n\n.parameter-panel {\n  display: grid;\n  align-content: start;\n  gap: 9px;\n}\n\n.parameter-state {\n  display: grid;\n  gap: 3px;\n  min-width: 0;\n  min-height: 54px;\n  align-content: center;\n  padding: 8px 10px;\n  border: 1px solid var(--line);\n  border-radius: var(--radius-small);\n  color: var(--muted);\n  background: #0d1219;\n  font-size: 0.7rem;\n  text-align: left;\n}\n\n.parameter-state strong {\n  overflow: hidden;\n  color: var(--text);\n  font: 600 0.73rem ui-monospace, SFMono-Regular, Menlo, monospace;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n\n.state-button { cursor: pointer; }\n\n.tool-disclosure {\n  overflow: visible;\n  box-shadow: none;\n}\n\n.tool-disclosure > summary {\n  display: flex;\n  min-height: var(--control-height);\n  align-items: center;\n  justify-content: space-between;\n  gap: 12px;\n  padding: 8px 10px;\n  cursor: pointer;\n  list-style: none;\n}\n\n.tool-disclosure > summary::-webkit-details-marker { display: none; }\n.tool-disclosure > summary span:last-child,\n.tool-disclosure > summary strong {\n  overflow: hidden;\n  color: var(--muted);\n  font-size: 0.72rem;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n\n.settings-body,\n.compact-settings,\n.compact-actions,\n.shortcut-grid {\n  border-top: 1px solid var(--line);\n}\n\n.compact-actions {\n  display: grid;\n  grid-template-columns: 1fr 1fr;\n  gap: 6px;\n  padding: 9px;\n}\n\n.compact-actions button {\n  min-height: var(--compact-control-height);\n  padding: 5px 7px;\n  font-size: 0.7rem;\n}\n\n.step-field-settings {\n  display: grid;\n  gap: 8px;\n  padding: 9px;\n}\n\n.step-field-settings fieldset {\n  display: grid;\n  gap: 8px;\n  margin: 0;\n  padding: 9px;\n  border: 1px solid var(--line);\n  border-radius: 8px;\n}\n\n.step-field-settings legend {\n  padding: 0 5px;\n  color: var(--muted);\n  font-size: 0.7rem;\n}\n\n.link-setting,\n.number-setting {\n  display: grid;\n  grid-template-columns: minmax(0, 1fr) auto;\n  align-items: center;\n  gap: 9px;\n  color: var(--muted);\n  font-size: 0.72rem;\n}\n\n.link-setting {\n  grid-template-columns: auto minmax(0, 1fr);\n}\n\n.link-setting input { min-height: 0; }\n.number-setting input { width: 92px; }\n\n.observation-settings .compact-settings {\n  display: grid;\n  grid-template-columns: 1fr 1fr;\n  gap: 8px;\n  padding: 9px;\n}\n\n.compact-setting {\n  display: grid;\n  gap: 5px;\n  color: var(--muted);\n  font-size: 0.72rem;\n}\n\n.capture-bar {\n  display: grid;\n  gap: 8px;\n  padding: 9px;\n  border: 1px solid rgba(246, 200, 110, 0.35);\n  border-radius: var(--radius-small);\n  background: rgba(246, 200, 110, 0.07);\n}\n\n.capture-bar strong {\n  display: block;\n  margin-top: 2px;\n  font-size: 0.75rem;\n}\n\n.capture-actions {\n  display: grid;\n  grid-template-columns: 1fr 1fr;\n  gap: 7px;\n}\n\n.shortcut-grid {\n  display: grid;\n  grid-template-columns: 1fr 1fr;\n  gap: 7px 12px;\n  padding: 9px 10px 10px;\n  color: var(--muted);\n  font-size: 0.72rem;\n}\n\n.navigation-panel {\n  display: flex;\n  min-width: 0;\n  flex-direction: column;\n}\n\n.navigation-heading {\n  align-items: center;\n}\n\n.navigation-deck {\n  display: grid;\n  grid-template-columns: repeat(3, minmax(0, 1fr));\n  grid-template-areas:\n    ". reopen ."\n    "refine-backward . refine-forward"\n    "step-backward return step-forward"\n    "pin-backward pin-current pin-forward";\n  gap: 8px;\n  align-items: stretch;\n  margin: auto 0;\n}\n\n#reopen { grid-area: reopen; }\n#refine-backward { grid-area: refine-backward; }\n#refine-forward { grid-area: refine-forward; }\n#step-backward { grid-area: step-backward; }\n#return-action { grid-area: return; }\n#step-forward { grid-area: step-forward; }\n#pin-backward { grid-area: pin-backward; }\n#pin-current { grid-area: pin-current; }\n#pin-forward { grid-area: pin-forward; }\n\n.nav-action {\n  display: flex;\n  min-width: 0;\n  min-height: 66px;\n  flex-direction: column;\n  align-items: center;\n  justify-content: center;\n  gap: 4px;\n  padding: 8px 9px;\n  text-align: center;\n}\n\n.nav-action.direction.backward { border-left-color: rgba(172, 184, 205, 0.48); }\n.nav-action.direction.forward { border-right-color: rgba(121, 168, 255, 0.62); }\n\n.history-action {\n  border-color: rgba(159, 217, 184, 0.5);\n  background: rgba(159, 217, 184, 0.09);\n}\n\n.reopen-action {\n  border-color: rgba(188, 154, 255, 0.45);\n  background: rgba(188, 154, 255, 0.06);\n}\n\n.pin-current-action {\n  border-color: rgba(246, 200, 110, 0.5);\n  background: rgba(246, 200, 110, 0.08);\n}\n\n.action-name {\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  gap: 5px;\n  font-size: 0.82rem;\n}\n\n.action-meta {\n  max-width: 100%;\n  overflow: hidden;\n  color: var(--muted);\n  font-size: 0.69rem;\n  line-height: 1.3;\n  text-overflow: ellipsis;\n}\n\n/* Guide is the only retained-structure surface. */\n.guide-panel {\n  display: flex;\n  min-width: 0;\n  min-height: 480px;\n  max-height: min(760px, calc(100vh - 32px));\n  flex-direction: column;\n  overflow: hidden;\n  padding: 0;\n  box-shadow: 0 10px 34px rgba(0, 0, 0, 0.18);\n}\n\n.guide-header {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: 10px;\n  padding: 12px;\n  border-bottom: 1px solid var(--line);\n}\n\n.guide-header-actions {\n  display: flex;\n  align-items: center;\n  gap: 7px;\n}\n\n.guide-counts {\n  color: var(--muted);\n  font-size: 0.7rem;\n  white-space: nowrap;\n}\n\n.guide-close {\n  display: none;\n  width: 36px;\n  padding: 0;\n  font-size: 1.25rem;\n}\n\n.guide-tabs {\n  display: grid;\n  grid-template-columns: 1fr 1fr 1fr;\n  gap: 5px;\n  padding: 8px;\n  border-bottom: 1px solid var(--line);\n}\n\n.guide-tab {\n  min-height: 36px;\n  padding: 5px 6px;\n  color: var(--muted);\n  font-size: 0.75rem;\n}\n\n.guide-tab.active {\n  border-color: rgba(121, 168, 255, 0.5);\n  color: var(--text);\n  background: var(--accent-soft);\n}\n\n.focused-section {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: 10px;\n  padding: 9px 11px;\n  border-bottom: 1px solid var(--line);\n  background: rgba(121, 168, 255, 0.08);\n}\n\n.focused-section div {\n  display: grid;\n  gap: 2px;\n  min-width: 0;\n}\n\n.focused-section strong,\n.focused-section span:last-child {\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n\n.focused-section span:last-child {\n  color: var(--muted);\n  font-size: 0.71rem;\n}\n\n.guide-tab-panel {\n  min-height: 0;\n  flex: 1;\n  overflow: auto;\n  overscroll-behavior: contain;\n}\n\n.guide-list {\n  display: grid;\n  gap: 7px;\n  padding: 8px;\n}\n\n.empty-state {\n  padding: 16px 10px;\n  text-align: center;\n  font-size: 0.78rem;\n}\n\n.guide-item {\n  overflow: hidden;\n  border: 1px solid var(--line);\n  border-radius: 9px;\n  background: #0d1219;\n}\n\n.guide-item.focused { border-color: rgba(121, 168, 255, 0.6); }\n\n.guide-item-main {\n  display: grid;\n  width: 100%;\n  gap: 3px;\n  padding: 9px;\n  border: 0;\n  border-radius: 0;\n  background: transparent;\n  text-align: left;\n}\n\n.guide-item-title {\n  overflow: hidden;\n  font-weight: 680;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n\n.guide-item-time {\n  color: var(--muted);\n  font-size: 0.7rem;\n}\n\n.guide-item-actions {\n  display: flex;\n  gap: 5px;\n  padding: 0 8px 8px;\n}\n\n.guide-item-actions button {\n  min-height: 30px;\n  padding: 3px 7px;\n  font-size: 0.69rem;\n}\n\n.danger-text { color: var(--danger); }\n\n.section-endpoints {\n  display: grid;\n  grid-template-columns: 1fr auto 1fr;\n  gap: 5px;\n  align-items: center;\n  padding: 0 8px 8px;\n  color: var(--muted);\n}\n\n.endpoint-button {\n  display: grid;\n  min-width: 0;\n  min-height: 36px;\n  gap: 1px;\n  padding: 5px 7px;\n  text-align: left;\n}\n\n.endpoint-button small {\n  color: var(--faint);\n  font-size: 0.58rem;\n  text-transform: uppercase;\n}\n\n.endpoint-button span {\n  overflow: hidden;\n  font-size: 0.67rem;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n\n.source-placeholder { padding: 18px; }\n.source-placeholder p {\n  margin-top: 8px;\n  font-size: 0.79rem;\n}\n\n.guide-scrim { display: none; }\n\n.guide-dialog {\n  width: min(420px, calc(100vw - 24px));\n  padding: 0;\n  border: 1px solid var(--line-strong);\n  border-radius: 14px;\n  color: var(--text);\n  background: #111824;\n  box-shadow: var(--shadow);\n}\n\n.guide-dialog::backdrop { background: rgba(0, 0, 0, 0.66); }\n\n.guide-dialog form {\n  display: grid;\n  gap: 12px;\n  padding: 16px;\n}\n\n.dialog-heading { display: grid; gap: 2px; }\n.guide-dialog label { color: var(--muted); font-size: 0.76rem; }\n\n.dialog-actions {\n  display: flex;\n  justify-content: flex-end;\n  gap: 8px;\n}\n\n/* The one wide-desktop layout owner. */\n@media (min-width: 1221px) {\n  .command-workspace {\n    grid-template-columns:\n      minmax(260px, 0.78fr)\n      minmax(520px, 1.5fr)\n      minmax(300px, 0.92fr);\n  }\n\n  .parameter-panel,\n  .navigation-panel,\n  .guide-panel {\n    min-height: 520px;\n  }\n\n  .guide-panel {\n    position: sticky;\n    top: 12px;\n  }\n}\n\n@media (max-width: 1220px) {\n  .command-workspace {\n    grid-template-columns: minmax(250px, 0.82fr) minmax(470px, 1.18fr);\n  }\n\n  .guide-panel {\n    grid-column: 1 / -1;\n    min-height: 360px;\n    max-height: 460px;\n  }\n}\n\n@media (max-width: 900px) {\n  .app-shell { padding: 8px; }\n\n  .load-bar {\n    position: sticky;\n    top: 0;\n    z-index: 60;\n    padding: 8px;\n  }\n\n  .brand-block p { display: none; }\n\n  .load-actions {\n    flex: 1;\n    justify-content: flex-end;\n  }\n\n  .url-row {\n    grid-template-columns: minmax(0, 1fr) auto;\n    width: min(100%, 560px);\n  }\n\n  .command-workspace {\n    grid-template-columns: minmax(0, 1fr);\n  }\n\n  .navigation-panel { order: 1; }\n  .parameter-panel { order: 2; }\n\n  .guide-panel {\n    position: fixed;\n    z-index: 100;\n    top: 0;\n    right: 0;\n    bottom: 0;\n    width: min(92vw, 420px);\n    min-height: 0;\n    max-height: none;\n    border-radius: 14px 0 0 14px;\n    transform: translateX(104%);\n    transition: transform 180ms ease;\n    box-shadow: var(--shadow);\n  }\n\n  .guide-panel.is-open { transform: translateX(0); }\n  .guide-panel[aria-hidden="true"] { visibility: hidden; }\n\n  .guide-close {\n    display: inline-grid;\n    place-items: center;\n  }\n\n  .guide-scrim {\n    position: fixed;\n    z-index: 90;\n    inset: 0;\n    display: block;\n    min-height: 0;\n    border: 0;\n    border-radius: 0;\n    background: rgba(0, 0, 0, 0.58);\n  }\n\n  .guide-scrim[hidden] { display: none; }\n}\n\n@media (max-width: 680px) {\n  .load-bar { align-items: flex-start; }\n  .brand-block { display: none; }\n  .load-actions { width: 100%; }\n  .guide-toggle kbd { display: none; }\n\n  .reader-column { gap: 8px; }\n  .panel { padding: 9px; }\n  .panel-heading { margin-bottom: 8px; }\n  .compact-heading p,\n  .navigation-heading p { display: none; }\n\n  .timeline {\n    margin-inline: 2px;\n  }\n\n  .timeline-header {\n    gap: 9px;\n  }\n\n  .navigation-deck {\n    gap: 6px;\n  }\n\n  .nav-action {\n    min-height: 62px;\n    padding: 7px 5px;\n  }\n\n  .action-name {\n    gap: 3px;\n    font-size: 0.75rem;\n  }\n\n  .action-meta {\n    font-size: 0.63rem;\n  }\n\n  .observation-settings .compact-settings,\n  .shortcut-grid {\n    grid-template-columns: minmax(0, 1fr);\n  }\n\n  .capture-actions,\n  .compact-actions {\n    grid-template-columns: 1fr;\n  }\n}\n\n@media (pointer: coarse) {\n  button,\n  summary,\n  input,\n  select {\n    min-height: var(--touch);\n  }\n\n  .timeline-pin {\n    width: 22px;\n    height: 22px;\n  }\n}\n')
write('step-field.css', '/* Panoramic physical projection of Step Backward | Current | Step Forward. */\n.step-field {\n  --field-gap: clamp(8px, 0.8vw, 14px);\n  display: grid;\n  grid-template-columns:\n    minmax(250px, 1fr)\n    minmax(500px, 1.62fr)\n    minmax(250px, 1fr);\n  gap: var(--field-gap);\n  align-items: center;\n  padding: var(--field-gap);\n  background: #080c11;\n}\n\n.step-pane {\n  position: relative;\n  min-width: 0;\n  overflow: hidden;\n  border: 1px solid var(--line);\n  border-radius: 11px;\n  background: #05070a;\n}\n\n.step-pane-center {\n  border-color: var(--line-strong);\n  box-shadow: 0 14px 32px rgba(0, 0, 0, 0.28);\n}\n\n.step-pane-side {\n  align-self: center;\n  opacity: 0.92;\n}\n\n.step-pane-side .player-wrap {\n  filter: saturate(0.82) brightness(0.82);\n  transition: filter 120ms ease;\n}\n\n.step-pane-side:hover .player-wrap,\n.step-pane-side:focus-within .player-wrap {\n  filter: saturate(0.94) brightness(0.94);\n}\n\n.step-pane-bar {\n  position: relative;\n  z-index: 7;\n  display: flex;\n  min-height: var(--control-height);\n  align-items: center;\n  justify-content: space-between;\n  gap: 8px;\n  padding: 5px 6px 5px 9px;\n  border-bottom: 1px solid var(--line);\n  background: #0d131b;\n}\n\n.pane-identity {\n  display: flex;\n  min-width: 0;\n  align-items: baseline;\n  gap: 7px;\n}\n\n.step-pane-role {\n  flex: 0 0 auto;\n  color: var(--text);\n  font-size: 0.66rem;\n  font-weight: 760;\n  letter-spacing: 0.09em;\n  text-transform: uppercase;\n}\n\n.step-pane-meta {\n  min-width: 0;\n  overflow: hidden;\n  color: #c0cad6;\n  font: 600 0.65rem/1.2 ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n\n.pane-controls {\n  display: flex;\n  flex: 0 0 auto;\n  align-items: center;\n  gap: 5px;\n}\n\n.pane-rate-setting {\n  display: inline-flex;\n  align-items: center;\n  gap: 5px;\n  color: var(--muted);\n  font-size: 0.64rem;\n}\n\n.pane-rate-setting select {\n  width: 78px;\n  min-width: 78px;\n  min-height: var(--compact-control-height);\n  height: var(--compact-control-height);\n  padding: 0 1.35rem 0 0.45rem;\n  border-color: rgba(116, 134, 157, 0.62);\n  background: #111823;\n  font-size: 0.67rem;\n}\n\n.pane-collapse,\n.field-toggle {\n  min-height: var(--compact-control-height);\n  border-color: rgba(116, 134, 157, 0.62);\n  background: #111823;\n}\n\n.pane-collapse {\n  width: 30px;\n  padding: 0;\n  font-size: 0.95rem;\n}\n\n.field-toggle {\n  display: inline-flex;\n  align-items: center;\n  gap: 5px;\n  padding: 0 8px;\n  font-size: 0.67rem;\n}\n\n.field-toggle span:last-child { color: var(--muted); }\n.field-toggle[aria-pressed="true"] { border-color: rgba(121, 168, 255, 0.62); }\n\n.step-pane-action {\n  position: absolute;\n  z-index: 5;\n  inset: 0;\n  width: 100%;\n  min-height: 0;\n  padding: 0;\n  border: 0;\n  border-radius: 0;\n  background: transparent;\n}\n\n.step-pane-action:hover:not(:disabled),\n.step-pane-action:focus-visible {\n  background: rgba(121, 168, 255, 0.08);\n  box-shadow: inset 0 0 0 2px rgba(121, 168, 255, 0.46);\n}\n\n.step-pane-action:disabled { opacity: 1; }\n\n.step-pane-restore {\n  position: absolute;\n  inset: 0;\n  display: flex;\n  min-height: 0;\n  align-items: center;\n  justify-content: center;\n  gap: 3px;\n  padding: 0;\n  border: 0;\n  border-radius: 0;\n  color: var(--muted);\n  background: #111721;\n  writing-mode: vertical-rl;\n}\n\n.step-pane.is-collapsed {\n  min-height: 180px;\n}\n\n.step-pane.is-collapsed .player-wrap,\n.step-pane.is-collapsed .step-pane-bar {\n  display: none;\n}\n\n.step-field.field-off {\n  grid-template-columns: minmax(0, 1fr);\n}\n\n.step-field.field-off .step-pane-side { display: none; }\n.step-field.field-off .step-pane-center {\n  width: min(1100px, 100%);\n  justify-self: center;\n}\n\n.step-field.tail-collapsed {\n  grid-template-columns: 48px minmax(500px, 1.62fr) minmax(250px, 1fr);\n}\n\n.step-field.lead-collapsed {\n  grid-template-columns: minmax(250px, 1fr) minmax(500px, 1.62fr) 48px;\n}\n\n.step-field.tail-collapsed.lead-collapsed {\n  grid-template-columns: 48px minmax(500px, 1fr) 48px;\n}\n\n.step-field.is-suspended .step-pane-side .player-wrap {\n  filter: grayscale(0.35) brightness(0.58);\n}\n\n@media (max-width: 1180px) {\n  .step-field,\n  .step-field.tail-collapsed,\n  .step-field.lead-collapsed,\n  .step-field.tail-collapsed.lead-collapsed {\n    grid-template-columns: repeat(2, minmax(0, 1fr));\n  }\n\n  .step-pane-center {\n    grid-column: 1 / -1;\n    grid-row: 1;\n    width: min(900px, 100%);\n    justify-self: center;\n  }\n\n  .tail-pane {\n    grid-column: 1;\n    grid-row: 2;\n  }\n\n  .lead-pane {\n    grid-column: 2;\n    grid-row: 2;\n  }\n\n  .step-pane.is-collapsed {\n    min-height: 64px;\n  }\n\n  .step-pane-restore {\n    writing-mode: horizontal-tb;\n  }\n}\n\n@media (max-width: 680px) {\n  .step-field,\n  .step-field.tail-collapsed,\n  .step-field.lead-collapsed,\n  .step-field.tail-collapsed.lead-collapsed {\n    grid-template-columns: minmax(0, 1fr);\n    gap: 7px;\n    padding: 7px;\n  }\n\n  .step-pane-center {\n    grid-column: 1;\n    grid-row: 1;\n  }\n\n  .tail-pane {\n    grid-column: 1;\n    grid-row: 2;\n  }\n\n  .lead-pane {\n    grid-column: 1;\n    grid-row: 3;\n  }\n\n  .step-pane-side .player-wrap {\n    min-height: 200px;\n    aspect-ratio: auto;\n  }\n\n  .step-pane-bar {\n    min-height: 50px;\n  }\n\n  .pane-rate-setting > span {\n    display: none;\n  }\n\n  .step-pane-meta {\n    font-size: 0.59rem;\n  }\n}\n\n@media (pointer: coarse) {\n  .pane-rate-setting select,\n  .pane-collapse,\n  .field-toggle {\n    min-height: var(--touch);\n    height: var(--touch);\n  }\n\n  .pane-rate-setting select {\n    width: 92px;\n    min-width: 92px;\n    font-size: 16px;\n  }\n\n  .pane-collapse {\n    width: var(--touch);\n  }\n}\n')
write('field-grammar.css', '/* Field phase, playback dock, and operand presentation. */\n.step-field {\n  position: relative;\n  isolation: isolate;\n}\n\n.step-field::before {\n  content: "";\n  position: absolute;\n  z-index: 0;\n  inset: 22% 14% 20%;\n  border-radius: 999px;\n  background: linear-gradient(90deg,\n    rgba(121, 168, 255, 0.03),\n    rgba(121, 168, 255, 0.15) 36%,\n    rgba(255, 255, 255, 0.08) 50%,\n    rgba(121, 168, 255, 0.15) 64%,\n    rgba(121, 168, 255, 0.03));\n  filter: blur(16px);\n  opacity: 0;\n  transform: scaleX(0.48);\n  transition: opacity 220ms ease, transform 520ms cubic-bezier(.2,.72,.2,1);\n  pointer-events: none;\n}\n\n.step-field[data-phase="unfolding"]::before,\n.step-field[data-phase="partially-held"]::before {\n  opacity: 0.34;\n  transform: scaleX(0.88);\n}\n\n.step-field[data-phase="held"]::before {\n  opacity: 0.13;\n  transform: scaleX(1);\n}\n\n.step-pane { z-index: 1; }\n\n.step-pane-side {\n  transition: transform 360ms cubic-bezier(.2,.72,.2,1), opacity 220ms ease, filter 220ms ease;\n  will-change: transform;\n}\n\n.step-field[data-phase="coincident"] .tail-pane,\n.step-field[data-phase="coincident"] .lead-pane {\n  opacity: 0.75;\n}\n\n.step-field[data-phase="unfolding"] .tail-pane {\n  transform: translateX(-4px) scale(.988);\n  filter: blur(.35px);\n}\n\n.step-field[data-phase="unfolding"] .lead-pane {\n  transform: translateX(4px) scale(.988);\n  filter: blur(.35px);\n}\n\n.step-field[data-phase="partially-held"] .step-pane-side {\n  filter: blur(.18px);\n}\n\n.step-field[data-phase="held"] .step-pane-side {\n  opacity: 0.94;\n  transform: translateX(0) scale(1);\n  filter: none;\n}\n\n/* Playback is attached directly to the panoramic media surface. */\n.field-transport-bar {\n  display: grid;\n  grid-template-columns: auto minmax(320px, 1fr) auto;\n  align-items: center;\n  gap: 10px;\n  padding: 8px 10px;\n  border-top: 1px solid var(--line);\n  background: #0d1219;\n}\n\n.transport-actions {\n  display: flex;\n  align-items: center;\n  gap: 6px;\n}\n\n.field-transport,\n.transport-action {\n  display: inline-flex;\n  min-height: var(--control-height);\n  align-items: center;\n  justify-content: center;\n  gap: 7px;\n  padding: 0 10px;\n  white-space: nowrap;\n}\n\n.field-transport {\n  min-width: 148px;\n  border-color: rgba(121, 168, 255, 0.62);\n  background: rgba(20, 30, 43, 0.9);\n}\n\n.field-transport.is-active {\n  border-color: rgba(255, 196, 104, 0.72);\n}\n\n.transport-action {\n  min-width: 86px;\n  color: var(--muted);\n  background: rgba(13, 19, 27, 0.78);\n}\n\n.transport-action:hover:not(:disabled),\n.transport-action:focus-visible {\n  color: var(--text);\n  border-color: rgba(121, 168, 255, 0.62);\n}\n\n.control-meta {\n  color: var(--muted);\n  font-size: 0.68rem;\n}\n\n.transport-readouts {\n  display: flex;\n  min-width: 0;\n  align-items: stretch;\n  justify-content: center;\n  gap: 6px;\n}\n\n.transport-readout {\n  display: grid;\n  min-width: 118px;\n  max-width: 240px;\n  gap: 2px;\n  align-content: center;\n  padding: 5px 8px;\n  border: 1px solid var(--line);\n  border-radius: 8px;\n  color: var(--muted);\n  background: #0a0f16;\n  font-size: 0.64rem;\n  text-align: left;\n}\n\n.transport-readout strong {\n  overflow: hidden;\n  color: var(--text);\n  font: 600 0.68rem ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n\n.operand-readout {\n  position: relative;\n  padding-right: 46px;\n}\n\n.operand-readout em {\n  position: absolute;\n  top: 50%;\n  right: 8px;\n  color: var(--pin);\n  font-size: 0.62rem;\n  font-style: normal;\n  transform: translateY(-50%);\n}\n\n.field-span-state {\n  display: flex;\n  max-width: 360px;\n  align-items: stretch;\n  padding: 0;\n  border-color: rgba(121, 168, 255, 0.34);\n}\n\n.field-span-state > div:first-child {\n  display: grid;\n  min-width: 0;\n  flex: 1;\n  gap: 2px;\n  align-content: center;\n  padding: 5px 8px;\n}\n\n.extent-actions {\n  display: flex;\n  align-items: stretch;\n}\n\n.extent-action {\n  min-height: 100%;\n  padding: 0 8px;\n  border-width: 0 0 0 1px;\n  border-radius: 0;\n  color: var(--muted);\n  background: rgba(13, 19, 27, 0.78);\n  font-size: 0.65rem;\n}\n\n.extent-action:hover:not(:disabled),\n.extent-action:focus-visible {\n  color: var(--text);\n  border-color: rgba(121, 168, 255, 0.62);\n}\n\n.transport-status {\n  display: grid;\n  min-width: 190px;\n  gap: 2px;\n  justify-items: end;\n}\n\n.field-transport-state,\n.field-rate-state {\n  overflow: hidden;\n  max-width: 100%;\n  color: var(--muted);\n  font-size: 0.68rem;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n\n.field-transport-state {\n  color: var(--text);\n  font-weight: 650;\n}\n\n.field-span-fill {\n  position: absolute;\n  inset-block: 5px;\n  border: 1px solid rgba(121, 168, 255, 0.48);\n  border-radius: 999px;\n  background: linear-gradient(90deg, rgba(121,168,255,.05), rgba(121,168,255,.14), rgba(121,168,255,.05));\n  pointer-events: none;\n}\n\n.capture-source { color: var(--muted); }\n\n@media (max-width: 1120px) {\n  .field-transport-bar {\n    grid-template-columns: minmax(0, 1fr) auto;\n  }\n\n  .transport-readouts {\n    grid-column: 1 / -1;\n    justify-content: flex-start;\n    overflow-x: auto;\n    padding-bottom: 1px;\n  }\n}\n\n@media (max-width: 680px) {\n  .step-field::before {\n    inset: 18% 6% 10%;\n  }\n\n  .field-transport-bar {\n    grid-template-columns: minmax(0, 1fr);\n    gap: 7px;\n  }\n\n  .transport-actions {\n    display: grid;\n    grid-template-columns: 1.25fr 1fr 1fr 1fr;\n  }\n\n  .field-transport,\n  .transport-action {\n    min-width: 0;\n    padding-inline: 6px;\n  }\n\n  .transport-readouts {\n    grid-column: 1;\n    justify-content: flex-start;\n  }\n\n  .transport-status {\n    min-width: 0;\n    justify-items: start;\n  }\n}\n\n@media (pointer: coarse) {\n  .field-transport,\n  .transport-action,\n  .extent-action {\n    min-height: var(--touch);\n  }\n}\n')
write('INTERFACE.md', '# Binary YouTube Reader — Interface Grammar\n\n## 1. Purpose\n\nThe interface is a projection of the operator grammar. A visible element is justified only when removing it would remove an available operation, conceal state required to predict an operation, or erase feedback needed to distinguish semantic commitment from physical observation.\n\nThe desktop composition has three ordered regions:\n\n```text\nPanoramic media\n→ playback and live operands\n→ full-width temporal map\n→ Parameters | Operator matrix | Guide\n```\n\nParameters alter operands. The centered matrix applies operators. The Guide retains explicit structure. These responsibilities do not overlap.\n\n## 2. Panoramic media\n\n| Element | Contribution | Consequence if removed |\n|---|---|---|\n| Tail pane | Shows the physical backward Step projection while Center remains authoritative | Backward material could not be compared simultaneously before committing Current |\n| Center pane | Owns audio, native YouTube controls, physical transport settlement, and semantic authority | The system would have no authoritative Cursor or audible reader |\n| Lead pane | Shows the physical forward Step projection while Center remains authoritative | Forward material could not be compared simultaneously before committing Current |\n| Tail/Lead rate control | Chooses a realizable directional playback response reported by that player | Formation kinetics would be fixed or falsely implied |\n| Field toggle | Returns the application to the stable single-player reader | The optional three-pane projection could not be disabled without changing source code |\n| Pane hide/restore | Removes one physical projection without changing Step semantics | A temporarily unwanted or unavailable pane would consume space permanently |\n\nPane headers are outside the video image. Controls never compete with YouTube titles, captions, or native overlays.\n\n## 3. Playback dock\n\nThe playback dock is attached directly to the media because its effects are physical and time-dependent.\n\n| Element | Contribution | Consequence if removed |\n|---|---|---|\n| Continue/Pause | Authoritative application gesture for Center and available side players | Three-player activation would depend only on delayed native iframe events |\n| Context | Observes around Current and restores it | Bounded local review would require semantic movement |\n| Skim | Traverses Center toward the forward structural target at an available rate | Fast structural forward reading would be lost |\n| Loop | Repeats the current stable explicit Extent | Repetition would require manual seeking and would lose operand identity |\n| Current readout | States the committed semantic Address | Physical Cursor movement could be mistaken for semantic commitment |\n| Interval readout and Retain affordance | Identifies the last committed movement Extent and opens Section capture | Loop/retention operands would be implicit and unrecoverable from the interface |\n| Field Span readout | Identifies the stable simultaneous Tail–Lead Extent | A Held Field could not be looped or retained as an explicit operand |\n| Field phase and rates | Reports whether the projection is Coincident, forming, Held, suspended, blocked, or rate-constrained | The interface could claim a relation that the players have not physically instantiated |\n\nRange, Resolution, and retained Section state do not belong in the playback dock because they are not playback commands.\n\n## 4. Temporal map\n\nThe temporal map spans the same width as the panoramic media. It is the spatial account of the active source.\n\n| Element | Contribution | Consequence if removed |\n|---|---|---|\n| Range fill and handles | Shows and edits the sole hard admissible domain | The user could not predict or directly alter boundary constraint |\n| Resolution fill | Shows the semantic Neighborhood scale within Range | Refine and Reopen targets would lack visible scale |\n| Current marker | Shows committed semantic position | Current could not be distinguished spatially from observed Cursor |\n| Cursor marker | Shows unsettled physical observation during transport | Physical motion would appear to commit immediately |\n| Interval fill | Shows the last movement Extent | The active Loop/retain operand would not be visible |\n| Field Span fill | Shows simultaneous Tail–Lead exposure | The live Field operand would be detached from source space |\n| Pin markers | Makes retained Addresses directly reachable | Retained point structure would exist only in the Guide list |\n| Target markers and previews | Show consequences before a command is committed | Directional operations would be less predictable |\n\nThe map does not repeat controls already owned by the playback dock or parameter panel.\n\n## 5. Parameter panel\n\nThe left panel contains entered values and bounded state that parameterize operators.\n\n| Element | Contribution | Consequence if removed |\n|---|---|---|\n| Active Range state | States the current admissible domain and opens Range tools | Boundary edits would become hidden gestures with no textual verification |\n| Resolution state | States the current semantic scale used by Refine/Reopen | The same Current could not be interpreted at its active grain |\n| Range tools | Provides explicit Start, Midpoint, End, and Full Video transformations | Range mutation would depend on dragging alone |\n| Step Reach | Defines independent backward and forward Step/Field geometry | Step destinations and Field targets could not be configured |\n| Context duration | Defines the Context observation window | Context would have an unexplained fixed duration |\n| Skim rate | Selects a realizable Center rate for Skim | Skim kinetics would be fixed or misleading |\n| Section capture | Names and confirms retention of an explicit Extent | Retention would create unlabeled or accidental structure |\n| Keyboard reference | Makes the compact command grammar discoverable | The Vim-like composition would exist only in documentation |\n\nNo operator button is placed in this panel. Changing a parameter is not the same act as applying an operator.\n\n## 6. Operator matrix\n\nThe centered matrix is the complete direct spatial command surface:\n\n```text\n        W\n     A     D\n     ←  S  →\n    ⇧←  P  ⇧→\n```\n\n| Position | Operator | Negated capability |\n|---|---|---|\n| W | Reopen | Cannot return to Range-level Resolution |\n| A / D | Refine Backward / Forward | Cannot choose one side of the Neighborhood |\n| ← / → | Step Backward / Forward | Cannot move by directional Reach |\n| S | Return | Cannot restore the preceding complete semantic checkpoint |\n| Shift+← / Shift+→ | Previous / next retained Pin | Cannot traverse retained Addresses directionally |\n| P | Pin Current | Cannot retain the current Address |\n\nStep Reach controls and Guide access are excluded because they are parameters and retained-structure presentation, not operators.\n\n## 7. Guide\n\nThe right panel is the only explicit retained-structure surface.\n\n| Element | Contribution | Consequence if removed |\n|---|---|---|\n| Sections tab | Lists retained bounded Extents and exposes Go, Focus, rename, and delete | Sections would persist without a management surface |\n| Pins tab | Lists retained Addresses and exposes Go, rename, and delete | Pins would be visible only as unlabeled map markers |\n| Sources tab | Keeps external potential structure distinct from retained Guide records | Source-provided structure could be mistaken for user commitment |\n| Focused Section state | Shows when a Section currently owns Range and provides Leave | Focus could silently replace the active domain |\n| Counts | Summarizes retained structure without adding a duplicate navigation button | The user could not assess retained density when a tab is not active |\n\nThere is no separate “Pins retained” matrix button. The Pin tab and directional Pin operators already provide the two required functions: management and traversal.\n\n## 8. Responsive behaviour\n\nDesktop is the primary composition. At narrower widths:\n\n1. Center moves above Tail and Lead.\n2. The operator matrix remains before parameter entry.\n3. Guide becomes a modal side sheet below 900 px.\n4. At phone widths, Tail and Lead stack and preserve the YouTube minimum player height.\n5. Controls preserve the shared coarse-pointer target.\n\nResponsive layout may change placement, but never ownership, terminology, or operator meaning.\n\n## 9. Admission rule for future UI\n\nA new element is admitted only when all are true:\n\n1. It exposes an implemented operation or irreducible state.\n2. Its owner is not already represented elsewhere.\n3. Its absence produces a specific lost capability or unrecoverable ambiguity.\n4. Its placement matches semantic ownership: media, playback, map, parameters, operators, or Guide.\n5. Automated integration and project audits can state the contract it preserves.\n\nVisual density is not evidence of capability. Empty or duplicative controls are defects.\n')
write('project-audit.mjs', 'import assert from "node:assert/strict";\nimport { readFileSync } from "node:fs";\n\nconst read = path => readFileSync(new URL(`./${path}`, import.meta.url), "utf8");\nconst pkg = JSON.parse(read("package.json"));\nconst html = read("index.html");\nconst styles = read("styles.css");\nconst fieldCss = read("step-field.css");\nconst grammarCss = read("field-grammar.css");\nconst app = read("app.js");\nconst view = read("view.js");\nconst field = read("step-field.js");\nconst fieldGeometry = read("step-field-geometry.js");\nconst youtube = read("youtube.js");\nconst docs = Object.fromEntries([\n  "README.md",\n  "SPEC.md",\n  "IMPLEMENTATION.md",\n  "INTERFACE.md",\n  "DEVELOPMENT.md",\n  "VALIDATION.md"\n].map(path => [path, read(path)]));\n\nassert.equal(pkg.version, "5.7.0");\nassert.equal(docs["SPEC.md"].startsWith("# Binary YouTube Reader — Canonical Specification\\n"), true);\nassert.equal(docs["IMPLEMENTATION.md"].startsWith("# Binary YouTube Reader — Canonical Implementation\\n"), true);\nassert.equal(docs["INTERFACE.md"].startsWith("# Binary YouTube Reader — Interface Grammar\\n"), true);\nfor (const name of ["SPEC.md", "IMPLEMENTATION.md", "INTERFACE.md", "DEVELOPMENT.md", "VALIDATION.md"]) {\n  assert.equal(docs["README.md"].includes("`" + name + "`"), true, `README must link ${name}`);\n}\n\nconst canonicalText = [html, ...Object.values(docs)].join("\\n");\nassert.doesNotMatch(html, /Step size/i, "Visible interface vocabulary must use Reach.");\nassert.match(docs["SPEC.md"], /scalar runtime Step size/, "Retired scalar vocabulary must remain explicitly classified as a non-contract.");\nassert.doesNotMatch(canonicalText, /Canonical (Specification|Implementation) v\\d/i, "Canonical documents must not embed stale release authority.");\n\nassert.match(html, /player-panel[\\s\\S]*timeline-panel[\\s\\S]*command-workspace/, "Media, map, and command workspace must preserve their vertical order.");\nassert.match(html, /command-workspace[\\s\\S]*parameter-panel[\\s\\S]*navigation-panel[\\s\\S]*guide-panel/, "Desktop command workspace must be Parameters | Operators | Guide.");\nassert.doesNotMatch(html, /id="pins-access"/, "Guide access must not duplicate retained-Pin traversal inside the operator matrix.");\nassert.doesNotMatch(html, /id="focused-state"/, "Focused Section state belongs to Guide, not playback or map controls.");\nassert.match(html, /transport-actions[\\s\\S]*id="continue"[\\s\\S]*id="context-action"[\\s\\S]*id="skim"[\\s\\S]*id="loop"/, "Playback and observation actions must share one dock.");\nassert.match(html, /id="tail-rate-select"[\\s\\S]*id="player-tail"/, "Tail rate must remain object-local.");\nassert.match(html, /id="lead-rate-select"[\\s\\S]*id="player-lead"/, "Lead rate must remain object-local.");\n\nassert.match(styles, /--control-height:\\s*40px/);\nassert.match(styles, /--compact-control-height:\\s*32px/);\nassert.match(styles, /--touch:\\s*48px/);\nassert.equal((styles.match(/@media \\(min-width: 1221px\\)/g) || []).length, 1, "Desktop layout must have one owner.");\nassert.doesNotMatch(fieldCss, /@media \\(min-width: 1221px\\)/, "Step Field CSS must not override application layout.");\nassert.match(styles, /grid-template-areas:[\\s\\S]*"\\. reopen \\."[\\s\\S]*"refine-backward \\. refine-forward"[\\s\\S]*"step-backward return step-forward"[\\s\\S]*"pin-backward pin-current pin-forward"/);\nassert.match(fieldCss, /grid-template-columns:[\\s\\S]*minmax\\(250px, 1fr\\)[\\s\\S]*minmax\\(500px, 1\\.62fr\\)[\\s\\S]*minmax\\(250px, 1fr\\)/);\nassert.match(grammarCss, /\\.field-transport-bar[\\s\\S]*\\.transport-actions[\\s\\S]*\\.transport-readouts[\\s\\S]*\\.transport-status/);\n\nfor (const dead of [\n  "interaction-grid",\n  "state-strip",\n  "secondary-tools",\n  "pins-access",\n  "focused-state",\n  "deck-spacer",\n  "settings-popover",\n  "guide-access"\n]) {\n  const selectorPattern = new RegExp(`\\\\.${dead}(?![A-Za-z0-9_-])`);\n  assert.equal(selectorPattern.test(`${styles}\\n${fieldCss}\\n${grammarCss}`), false, `Dead CSS selector remains: ${dead}`);\n}\n\nassert.match(styles, /@media \\(pointer: coarse\\)[\\s\\S]*button,[\\s\\S]*summary,[\\s\\S]*input,[\\s\\S]*select[\\s\\S]*min-height: var\\(--touch\\)/);\nassert.match(fieldCss, /@media \\(pointer: coarse\\)[\\s\\S]*\\.pane-collapse[\\s\\S]*height: var\\(--touch\\)/);\nassert.match(grammarCss, /@media \\(pointer: coarse\\)[\\s\\S]*\\.field-transport[\\s\\S]*min-height: var\\(--touch\\)/);\n\nassert.doesNotMatch(app, /pins-access|focused-state/, "Composition root must not bind removed duplicate controls.");\nassert.doesNotMatch(view, /pins-access-meta|focused-label|focused-state/, "Projection layer must not render removed duplicate controls.");\n\nassert.doesNotMatch(app, /const DEFAULT_FIELD_RESPONSE/, "Field response default must have one owner.");\nassert.match(fieldGeometry, /export const DEFAULT_FIELD_RESPONSE/);\nassert.match(fieldGeometry, /export function normalizeFieldResponse/);\nassert.doesNotMatch(fieldGeometry, /stepSeconds/, "Runtime Field geometry must accept directional Reach only.");\nassert.doesNotMatch(field, /globalThis\\.YT/, "Step Field must use the YouTube adapter readiness boundary.");\nassert.match(youtube, /export function isYouTubeApiReady/);\nassert.equal((`${app}\\n${field}\\n${fieldGeometry}`.match(/new\\s+(?:globalThis\\.)?YT\\.Player/g) || []).length, 0);\nassert.equal((youtube.match(/new\\s+globalThis\\.YT\\.Player/g) || []).length, 1);\n\nassert.match(pkg.scripts.audit, /integration-check\\.mjs/);\nassert.match(pkg.scripts.audit, /project-audit\\.mjs/);\nassert.match(pkg.scripts.check, /npm run audit/);\n\nconsole.log("Project audit passed: interface ownership, operator geometry, documentation authority, CSS boundaries, touch geometry, and adapter contracts are coherent.");\n')

